import type { NextRequest } from 'next/server';

import { setRefreshTokenCookie } from '@/server/auth/cookies';
import { requireBearerToken } from '@/server/auth/http';
import { getRequestMetadata, handleApiError, jsonOk } from '@/server/http';
import { exchangeOpenfortSession } from '@/server/services/auth';
import { readJsonObject } from '@/server/validation/public-forms';

function optionalString(body: Record<string, unknown>, field: string) {
  const value = body[field];
  return typeof value === 'string' ? value.trim() : undefined;
}

export async function POST(request: NextRequest) {
  try {
    const body = await readJsonObject(request);
    const login = await exchangeOpenfortSession({
      accessToken: requireBearerToken(request),
      firstName: optionalString(body, 'first_name'),
      lastName: optionalString(body, 'last_name'),
      organizationName: optionalString(body, 'organization_name'),
      phoneNumber: optionalString(body, 'phone_number'),
      email: optionalString(body, 'email'),
      type: optionalString(body, 'type'),
      role: optionalString(body, 'role'),
      metadata: getRequestMetadata(request),
    });
    const response = jsonOk({
      user_id: login.userId,
      access_token: login.accessToken,
      expires_at: login.accessTokenExpiresAt.toISOString(),
    });

    setRefreshTokenCookie(
      response,
      login.refreshToken,
      login.refreshTokenExpiresAt
    );

    return response;
  } catch (error) {
    return handleApiError(error);
  }
}

import 'server-only';

import { NextResponse } from 'next/server';

import {
  ApiError,
  internalServerError,
  isApiError,
  jsonError,
} from './api-error';
import { logger } from '@/server/logger';

export interface ApiSuccessBody<T> {
  code: 'OK';
  data: T;
}

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json<ApiSuccessBody<T>>(
    { code: 'OK', data },
    { status: init?.status ?? 200, headers: init?.headers }
  );
}

export function jsonNoContent() {
  return new NextResponse(null, { status: 204 });
}

export function handleApiError(error: unknown) {
  if (isApiError(error)) {
    return jsonError(error);
  }

  logger.error({ err: error }, 'Unhandled server error');
  return jsonError(internalServerError());
}

export function badRequest(message: string, detail?: string) {
  return new ApiError('BAD_REQUEST', message, { detail });
}

export function unauthorized(message = 'Unauthorized') {
  return new ApiError('UNAUTHORIZED', message);
}

import type { NextRequest } from 'next/server';

import { clearRefreshTokenCookie } from '@/server/auth/cookies';
import { requireBearerToken } from '@/server/auth/http';
import { handleApiError, jsonNoContent, jsonOk } from '@/server/http';
import {
  deleteCurrentAccount,
  getCurrentUser,
} from '@/server/services/account';

export async function GET(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    const user = await getCurrentUser(accessToken);

    return jsonOk(user);
  } catch (error) {
    return handleApiError(error);
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    await deleteCurrentAccount(accessToken);

    const response = jsonNoContent();
    clearRefreshTokenCookie(response);

    return response;
  } catch (error) {
    return handleApiError(error);
  }
}

import 'server-only';

import { ApiError } from '@/server/http';

export function requireBearerToken(request: Request) {
  const authorization = request.headers.get('authorization') ?? '';
  const prefix = 'Bearer ';

  if (!authorization.startsWith(prefix)) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  const token = authorization.slice(prefix.length).trim();

  if (!token) {
    throw new ApiError(
      'BAD_REQUEST',
      'Authorization bearer token is required.'
    );
  }

  return token;
}

import 'server-only';

import { authenticateAppRequest } from '@/server/services/auth';
import { ApiError } from '@/server/http';
import {
  findActiveUserById,
  softDeleteUserAccount,
  type UserWithOrganization,
} from '@/server/repositories/users';
import { deleteOpenfortUser } from '@/server/openfort/session';
import { logger } from '@/server/logger';

async function getAuthenticatedUser(accessToken: string) {
  const { user: sessionUser } = await authenticateAppRequest(accessToken);
  const user = await findActiveUserById(sessionUser.id);

  if (!user) {
    throw new ApiError('UNAUTHORIZED', 'Invalid access token.');
  }

  return user;
}

function isOrganization(user: UserWithOrganization) {
  return user.type === 'organization';
}

function isKycPending(user: UserWithOrganization) {
  return !Boolean(user.kycVerified);
}

function isKybPending(user: UserWithOrganization) {
  return isOrganization(user) && !Boolean(user.kybVerified);
}

function serializeTimestamp(value: Date | null) {
  return value?.toISOString() ?? null;
}

export async function getCurrentUser(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    openfort_user_id: user.openfortUserId,
    email: user.email,
    first_name: user.firstName,
    last_name: user.lastName,
    company_name: user.organization?.name ?? null,
    phone_number: user.phoneNumber,
    type: user.type,
    role: user.role,
    status: user.status,
    kyc_verified: Boolean(user.kycVerified),
    kyb_verified: Boolean(user.kybVerified),
  };
}

export async function getAccountStatus(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    openfort_user_id: user.openfortUserId,
    type: user.type,
    role: user.role,
    status: user.status,
    kyc_verified: Boolean(user.kycVerified),
    kyb_verified: Boolean(user.kybVerified),
    pending_kyc: isKycPending(user),
    pending_kyb: isKybPending(user),
  };
}

export async function getKycStatus(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);

  return {
    user_id: user.id,
    status: user.status,
    type: user.type,
    kyc_verified: Boolean(user.kycVerified),
    kyc_verified_at: serializeTimestamp(user.kycVerifiedAt),
    kyb_verified: Boolean(user.kybVerified),
    kyb_verified_at: serializeTimestamp(user.kybVerifiedAt),
    pending_kyc: isKycPending(user),
    pending_kyb: isKybPending(user),
  };
}

export async function deleteCurrentAccount(accessToken: string) {
  const user = await getAuthenticatedUser(accessToken);
  const openfortUserId = user.openfortUserId;

  await softDeleteUserAccount(user.id);

  try {
    await deleteOpenfortUser(openfortUserId);
  } catch (error) {
    logger.warn(
      { err: error, userId: user.id, openfortUserId },
      'Failed to delete Openfort user after local account deletion'
    );
  }
}

