input.content:
'use client';

import React, { useState } from 'react';
import {
  ArrowLeft,
  ArrowRight,
  ChartNoAxesCombined,
  CreditCard,
  HandHeart,
  Rocket,
} from 'lucide-react';
import CardView from '../ui/card-view';
import { CustomButton } from '../ui/custom-button';
import { FormInput } from '../ui/form-input';
import { useAuthSession } from '@/components/auth/auth-session-provider';
import {
  createProjectDraft,
  saveProjectCampaign,
  saveProjectContact,
  saveProjectInformation,
  saveProjectSymbol,
  submitProjectDraft,
  type ProjectCampaignPayload,
  type ProjectContactPayload,
  type ProjectInformationPayload,
  type ProjectResponse,
} from '@/lib/backend-auth-client';

type Step =
  | 'model'
  | 'symbol'
  | 'contact'
  | 'project'
  | 'campaign'
  | 'review'
  | 'submitted';

type MilestoneDraft = {
  name: string;
  cost: string;
  endDate: string;
};

const crowdfundingModels = [
  {
    title: 'Charity',
    description: 'Donation-based funding is coming later.',
    icon: HandHeart,
    disabled: true,
  },
  {
    title: 'Pre-Sale',
    description: 'Raise funds before launch with a base crowdfunding campaign.',
    icon: Rocket,
    disabled: false,
  },
  {
    title: 'Equity',
    description: 'Equity campaigns are coming later.',
    icon: ChartNoAxesCombined,
    disabled: true,
  },
  {
    title: 'Debt',
    description: 'Debt campaigns are coming later.',
    icon: CreditCard,
    disabled: true,
  },
];

const infrastructureOptions = [
  { value: 'wind_energy', label: 'Wind Energy' },
  { value: 'solar_power', label: 'Solar Power' },
  { value: 'hydroelectric', label: 'Hydroelectric' },
  { value: 'geothermal', label: 'Geothermal' },
  { value: 'nuclear', label: 'Nuclear' },
  { value: 'other', label: 'Other' },
];

const projectStatusOptions = [
  { value: 'ready_to_launch', label: 'Ready to launch' },
  { value: 'in_development', label: 'In Development' },
  { value: 'planning', label: 'Planning' },
  { value: 'on_hold', label: 'On Hold' },
  { value: 'completed', label: 'Completed' },
];

function SelectField({
  label,
  value,
  onChange,
  children,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  children: React.ReactNode;
}) {
  return (
    <label className="flex flex-col gap-2 text-sm font-medium text-white">
      {label}
      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-12 rounded-lg border border-transparent bg-[#131C2F] px-4 font-mono text-sm text-white outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/40"
      >
        {children}
      </select>
    </label>
  );
}

function TextareaField({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <label className="flex flex-col gap-2 text-sm font-medium text-white">
      {label}
      <textarea
        value={value}
        onChange={(event) => onChange(event.target.value)}
        rows={4}
        placeholder={label}
        className="rounded-lg border border-transparent bg-[#131C2F] px-4 py-3 font-mono text-sm text-white outline-none transition placeholder:text-[#51515E] focus:border-primary focus:ring-2 focus:ring-primary/40"
      />
    </label>
  );
}

function FieldValue({ label, value }: { label: string; value?: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="font-mono text-xs text-gray-400">{label}</span>
      <span className="chakra-petch text-base text-white">{value || '—'}</span>
    </div>
  );
}

export default function CreateProject() {
  const { backendAccessToken, backendUser } = useAuthSession();
  const [step, setStep] = useState<Step>('model');
  const [project, setProject] = useState<ProjectResponse | null>(null);
  const [symbol, setSymbol] = useState('');
  const [contact, setContact] = useState<ProjectContactPayload>({
    first_name: '',
    last_name: '',
    email: '',
    title: '',
    phone_number: '',
  });
  const [projectInfo, setProjectInfo] = useState<ProjectInformationPayload>({
    name: '',
    description: '',
    target_investment_amount: '',
    infrastructure_type: 'wind_energy',
    project_status: 'ready_to_launch',
    raised_before: false,
    website_url: '',
    social_url: '',
  });
  const [campaign, setCampaign] = useState<ProjectCampaignPayload>({
    token_name: '',
    digital_asset_supply: '',
    price: '',
    currency: 'USDC',
    min_raise: '',
    max_raise: '',
    min_contribution: '',
    max_contribution: '',
    start_date: '',
    end_date: '',
    general_contractor_wallet_address: '',
    pledge_address: '',
    milestones: [{ name: '', cost: '', end_date: '' }],
  });
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const canCreateProject = backendUser?.role === 'project_owner';

  async function persist<T>(action: () => Promise<T>, onSuccess: (value: T) => void) {
    if (!backendAccessToken) {
      setError('Please sign in again before creating a project.');
      return;
    }

    setIsSaving(true);
    setError(null);

    try {
      const result = await action();
      onSuccess(result);
    } catch (caughtError) {
      setError(caughtError instanceof Error ? caughtError.message : 'Request failed');
    } finally {
      setIsSaving(false);
    }
  }

  function updateContact(field: keyof ProjectContactPayload, value: string) {
    setContact((current) => ({ ...current, [field]: value }));
  }

  function updateProjectInfo(
    field: keyof ProjectInformationPayload,
    value: string | boolean | ProjectInformationPayload['proposal_document']
  ) {
    setProjectInfo((current) => ({ ...current, [field]: value }));
  }

  function updateCampaign(field: keyof ProjectCampaignPayload, value: string) {
    setCampaign((current) => ({ ...current, [field]: value }));
  }

  function updateMilestone(
    index: number,
    field: keyof MilestoneDraft,
    value: string
  ) {
    setCampaign((current) => ({
      ...current,
      milestones: current.milestones.map((milestone, currentIndex) =>
        currentIndex === index
          ? {
              ...milestone,
              [field === 'endDate' ? 'end_date' : field]: value,
            }
          : milestone
      ),
    }));
  }

  if (!canCreateProject) {
    return (
      <CardView width="1015px" height="728px" padding="p-12" className="gap-6">
        <div className="flex max-w-2xl flex-col gap-4">
          <span className="chakra-petch text-4xl font-semibold text-white">
            Create Project
          </span>
          <span className="font-mono text-sm leading-7 text-[#C7CAD5]">
            Project creation is available only for accounts with the
            project_owner role. Switch to a project owner account to apply for a
            new project setup.
          </span>
        </div>
      </CardView>
    );
  }

  return (
    <CardView
      width="1015px"
      height="auto"
      padding="p-12"
      className="min-h-[728px] gap-8"
    >
      <div className="flex w-full flex-col gap-2">
        <span className="chakra-petch text-4xl font-semibold text-white">
          {step === 'model' ? 'Choose crowdfunding models' : 'Application Form'}
        </span>
        <span className="font-mono text-sm leading-7 text-[#C7CAD5]">
          {step === 'model'
            ? 'The next step is choosing the right funding model. Let’s get you started!'
            : 'Complete your information to stay connected and receive updates.'}
        </span>
        {error ? (
          <div className="mt-2 rounded-lg border border-error/50 bg-error/10 px-4 py-3 font-mono text-xs text-error">
            {error}
          </div>
        ) : null}
      </div>

      {step === 'model' ? (
        <div className="flex w-full flex-col gap-4">
          {crowdfundingModels.map((item) => {
            const Icon = item.icon;

            return (
              <button
                key={item.title}
                type="button"
                disabled={item.disabled || isSaving}
                onClick={() =>
                  persist(
                    () => createProjectDraft(backendAccessToken!),
                    (draft) => {
                      setProject(draft);
                      setStep('symbol');
                    }
                  )
                }
                className={`flex min-h-[102px] w-full items-center gap-4 rounded-[20px] border px-6 text-left transition focus:outline-none focus:ring-2 focus:ring-primary/50 ${
                  item.disabled
                    ? 'cursor-not-allowed border-card-border bg-[#101827]/50 opacity-50'
                    : 'border-card-border bg-[#151E2F80] hover:border-primary/50 hover:bg-[#1F2A40]'
                }`}
              >
                <Icon className="size-10 text-primary" />
                <span className="flex flex-1 flex-col gap-1">
                  <span className="chakra-petch text-lg font-medium text-white">
                    {item.title}
                  </span>
                  <span className="font-mono text-sm text-[#8087A3]">
                    {item.description}
                  </span>
                </span>
                {item.disabled ? null : <ArrowRight className="text-white" />}
              </button>
            );
          })}
        </div>
      ) : null}

      {step === 'symbol' ? (
        <form
          className="flex w-full flex-1 flex-col justify-between gap-10"
          onSubmit={(event) => {
            event.preventDefault();
            if (!project) return;
            persist(
              () => saveProjectSymbol(backendAccessToken!, project.id, symbol),
              (updated) => {
                setProject(updated);
                setStep('contact');
              }
            );
          }}
        >
          <div className="w-[302px]">
            <FormInput
              label="Digital Asset Symbol"
              placeholder="e.g. $INF"
              value={symbol}
              onChange={(event) => setSymbol(event.target.value.toUpperCase())}
            />
            <p className="mt-2 font-mono text-xs text-gray-500">
              Use 3–6 letters or numbers. A leading $ is optional.
            </p>
          </div>
          <WizardActions onBack={() => setStep('model')} isSaving={isSaving} />
        </form>
      ) : null}

      {step === 'contact' ? (
        <form
          className="flex w-full flex-col gap-8"
          onSubmit={(event) => {
            event.preventDefault();
            if (!project) return;
            persist(
              () => saveProjectContact(backendAccessToken!, project.id, contact),
              (updated) => {
                setProject(updated);
                setStep('project');
              }
            );
          }}
        >
          <span className="chakra-petch text-3xl text-white">Contact information</span>
          <div className="grid grid-cols-2 gap-6">
            <FormInput label="First Name" placeholder="First Name" value={contact.first_name} onChange={(event) => updateContact('first_name', event.target.value)} />
            <FormInput label="Last Name" placeholder="Last Name" value={contact.last_name} onChange={(event) => updateContact('last_name', event.target.value)} />
            <FormInput label="Email" placeholder="Email" type="email" value={contact.email} onChange={(event) => updateContact('email', event.target.value)} />
            <FormInput label="Title" placeholder="Title" value={contact.title} onChange={(event) => updateContact('title', event.target.value)} />
            <FormInput label="Phone Number(optional)" placeholder="Phone Number" value={contact.phone_number} onChange={(event) => updateContact('phone_number', event.target.value)} />
          </div>
          <WizardActions onBack={() => setStep('symbol')} isSaving={isSaving} />
        </form>
      ) : null}

      {step === 'project' ? (
        <form
          className="flex w-full flex-col gap-8"
          onSubmit={(event) => {
            event.preventDefault();
            if (!project) return;
            persist(
              () => saveProjectInformation(backendAccessToken!, project.id, projectInfo),
              (updated) => {
                setProject(updated);
                setStep('campaign');
              }
            );
          }}
        >
          <span className="chakra-petch text-3xl text-white">Project information</span>
          <FormInput label="Project Name" placeholder="Project Name" value={projectInfo.name} onChange={(event) => updateProjectInfo('name', event.target.value)} className="w-[302px]" />
          <TextareaField label="Project Description" value={projectInfo.description} onChange={(value) => updateProjectInfo('description', value)} />
          <FormInput label="Target Investment Amount(£)" placeholder="Target Investment Amount(£)" value={projectInfo.target_investment_amount} onChange={(event) => updateProjectInfo('target_investment_amount', event.target.value)} />
          <div className="grid grid-cols-2 gap-6">
            <SelectField label="Project Type" value="renewable_energy" onChange={() => null}>
              <option value="renewable_energy">Renewable Energy</option>
            </SelectField>
            <SelectField label="Infrastructure Type" value={projectInfo.infrastructure_type} onChange={(value) => updateProjectInfo('infrastructure_type', value)}>
              {infrastructureOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
            </SelectField>
            <SelectField label="Project Status" value={projectInfo.project_status} onChange={(value) => updateProjectInfo('project_status', value)}>
              {projectStatusOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
            </SelectField>
            <SelectField label="Raised before ?" value={projectInfo.raised_before ? 'yes' : 'no'} onChange={(value) => updateProjectInfo('raised_before', value === 'yes')}>
              <option value="no">No</option>
              <option value="yes">Yes</option>
            </SelectField>
          </div>
          <FormInput label="Website Link" placeholder="URL" value={projectInfo.website_url} onChange={(event) => updateProjectInfo('website_url', event.target.value)} />
          <FormInput label="Social Media Link" placeholder="URL" value={projectInfo.social_url} onChange={(event) => updateProjectInfo('social_url', event.target.value)} />
          <label className="flex flex-col gap-2 text-sm font-medium text-white">
            Proposal File
            <input
              type="file"
              accept="application/pdf"
              onChange={(event) => {
                const file = event.target.files?.[0];
                updateProjectInfo(
                  'proposal_document',
                  file
                    ? {
                        file_name: file.name,
                        mime_type: file.type || 'application/pdf',
                        size_bytes: file.size,
                      }
                    : undefined
                );
              }}
              className="rounded-lg border border-dashed border-card-border bg-[#131C2F] px-4 py-4 font-mono text-sm text-gray-300 file:mr-4 file:rounded file:border-0 file:bg-primary file:px-4 file:py-2 file:text-black"
            />
          </label>
          <WizardActions onBack={() => setStep('contact')} isSaving={isSaving} />
        </form>
      ) : null}

      {step === 'campaign' ? (
        <form
          className="flex w-full flex-col gap-8"
          onSubmit={(event) => {
            event.preventDefault();
            if (!project) return;
            persist(
              () => saveProjectCampaign(backendAccessToken!, project.id, campaign),
              (updated) => {
                setProject(updated);
                setStep('review');
              }
            );
          }}
        >
          <span className="chakra-petch text-3xl text-white">Crowdfunding Campaign Details</span>
          <div className="grid grid-cols-2 gap-6">
            <FormInput label="Token Name" placeholder="Token Name" value={campaign.token_name} onChange={(event) => updateCampaign('token_name', event.target.value)} />
            <FormInput label="Digital Asset Supply" placeholder="Total supply" value={campaign.digital_asset_supply} onChange={(event) => updateCampaign('digital_asset_supply', event.target.value)} />
            <FormInput label="Price" placeholder="Price" value={campaign.price} onChange={(event) => updateCampaign('price', event.target.value)} />
            <FormInput label="Currency" placeholder="USDC" value={campaign.currency} onChange={(event) => updateCampaign('currency', event.target.value.toUpperCase())} />
            <FormInput label="Min Raise" placeholder="Min Raise" value={campaign.min_raise} onChange={(event) => updateCampaign('min_raise', event.target.value)} />
            <FormInput label="Max Raise" placeholder="Max Raise" value={campaign.max_raise} onChange={(event) => updateCampaign('max_raise', event.target.value)} />
            <FormInput label="Min Donation" placeholder="Min Donation" value={campaign.min_contribution} onChange={(event) => updateCampaign('min_contribution', event.target.value)} />
            <FormInput label="Max Donation" placeholder="Max Donation" value={campaign.max_contribution} onChange={(event) => updateCampaign('max_contribution', event.target.value)} />
            <FormInput label="Start Date" placeholder="Start Date" type="date" value={campaign.start_date} onChange={(event) => updateCampaign('start_date', event.target.value)} />
            <FormInput label="End Date" placeholder="End Date" type="date" value={campaign.end_date} onChange={(event) => updateCampaign('end_date', event.target.value)} />
          </div>
          <div className="flex flex-col gap-4">
            {campaign.milestones.map((milestone, index) => (
              <div key={index} className="rounded-[20px] border border-card-border bg-[#101827]/60 p-4">
                <h3 className="chakra-petch mb-4 text-lg text-white">Milestone {index + 1}</h3>
                <div className="grid grid-cols-3 gap-6">
                  <FormInput label="Name" placeholder="Name" value={milestone.name} onChange={(event) => updateMilestone(index, 'name', event.target.value)} />
                  <FormInput label="Cost" placeholder="Cost" value={milestone.cost} onChange={(event) => updateMilestone(index, 'cost', event.target.value)} />
                  <FormInput label="End Date" placeholder="End Date" type="date" value={milestone.end_date} onChange={(event) => updateMilestone(index, 'endDate', event.target.value)} />
                </div>
              </div>
            ))}
            <button
              type="button"
              onClick={() => setCampaign((current) => ({ ...current, milestones: [...current.milestones, { name: '', cost: '', end_date: '' }] }))}
              className="w-fit font-mono text-sm text-primary transition hover:text-primary-hover"
            >
              + Add milestone
            </button>
          </div>
          <FormInput label="General Contractor (GC) Wallet Address" placeholder="Wallet Address" value={campaign.general_contractor_wallet_address} onChange={(event) => updateCampaign('general_contractor_wallet_address', event.target.value)} />
          <FormInput label="Pledge Address" placeholder="Pledge Address" value={campaign.pledge_address} onChange={(event) => updateCampaign('pledge_address', event.target.value)} />
          <WizardActions onBack={() => setStep('project')} isSaving={isSaving} />
        </form>
      ) : null}

      {step === 'review' && project ? (
        <div className="flex w-full flex-col gap-8">
          <div>
            <span className="chakra-petch text-3xl text-white">Review & confirm your project details</span>
            <p className="mt-2 font-mono text-sm text-gray-400">
              Review your submission to make sure everything looks good.
            </p>
          </div>
          <div className="grid grid-cols-3 gap-8 border-b border-card-border pb-8">
            <FieldValue label="Project Name" value={project.name} />
            <FieldValue label="Symbol" value={project.digital_asset_symbol} />
            <FieldValue label="Token Name" value={project.campaign?.token_name} />
            <FieldValue label="Project Type" value="Renewable Energy" />
            <FieldValue label="Target Amount" value={`${project.target_investment_amount ?? '—'} ${project.target_investment_currency}`} />
            <FieldValue label="Crowdfunding" value="Pre-Sale" />
          </div>
          <FieldValue label="Project Description" value={project.description} />
          <div className="grid grid-cols-4 gap-8 border-t border-card-border pt-8">
            <FieldValue label="Name" value={project.contact ? `${project.contact.first_name} ${project.contact.last_name}` : null} />
            <FieldValue label="Email" value={project.contact?.email} />
            <FieldValue label="Phone" value={project.contact?.phone_number} />
            <FieldValue label="Title" value={project.contact?.title} />
          </div>
          <p className="font-mono text-xs text-gray-400">
            Once submitted, payment is skipped for this implementation and the project is stored for review.
          </p>
          <WizardActions
            onBack={() => setStep('campaign')}
            isSaving={isSaving}
            nextLabel="Submit Project"
            onSubmit={() =>
              persist(
                () => submitProjectDraft(backendAccessToken!, project.id),
                (updated) => {
                  setProject(updated);
                  setStep('submitted');
                }
              )
            }
          />
        </div>
      ) : null}

      {step === 'submitted' ? (
        <div className="flex flex-col gap-4">
          <span className="chakra-petch text-3xl text-white">Project submitted</span>
          <p className="font-mono text-sm leading-7 text-[#C7CAD5]">
            Your Pre-Sale project draft has been saved and submitted for setup review.
          </p>
        </div>
      ) : null}
    </CardView>
  );
}

function WizardActions({
  onBack,
  onSubmit,
  isSaving,
  nextLabel = 'Continue',
}: {
  onBack: () => void;
  onSubmit?: () => void;
  isSaving: boolean;
  nextLabel?: string;
}) {
  return (
    <div className="flex w-full items-center justify-between pt-4">
      <CustomButton
        type="button"
        variant="canceled"
        className="flex h-11 w-32 items-center justify-center gap-2 text-sm"
        onClick={onBack}
        disabled={isSaving}
      >
        <ArrowLeft size={20} />
        Back
      </CustomButton>
      <CustomButton
        type={onSubmit ? 'button' : 'submit'}
        variant="filled"
        className="flex h-11 w-fit items-center justify-center text-sm"
        onClick={onSubmit}
        disabled={isSaving}
      >
        {isSaving ? 'Saving…' : nextLabel}
      </CustomButton>
    </div>
  );
}

