import 'server-only';

import { Prisma } from '@prisma/client';

import { getDb } from '@/server/db';
import type {
  CampaignInput,
  ContactInput,
  ProjectInformationInput,
  ProjectSymbolInput,
} from '@/server/validation/projects';

const projectInclude = {
  campaign: true,
  contact: true,
  documents: true,
  milestones: {
    orderBy: {
      sortOrder: 'asc' as const,
    },
  },
} satisfies Prisma.ProjectInclude;

export type ProjectWithDetails = Prisma.ProjectGetPayload<{
  include: typeof projectInclude;
}>;

export function createProjectDraft(ownerUserId: string) {
  return getDb().project.create({
    data: {
      ownerUserId,
      crowdfundingModel: 'pre_sale',
      currentStep: 'asset_symbol',
    },
    include: projectInclude,
  });
}

export function findProjectForOwner(projectId: string, ownerUserId: string) {
  return getDb().project.findFirst({
    where: {
      id: projectId,
      ownerUserId,
    },
    include: projectInclude,
  });
}

export function updateProjectSymbol(
  projectId: string,
  input: ProjectSymbolInput
) {
  return getDb().project.update({
    where: {
      id: projectId,
    },
    data: {
      digitalAssetSymbol: input.digitalAssetSymbol,
      currentStep: 'contact_information',
      updatedAt: new Date(),
    },
    include: projectInclude,
  });
}

export function upsertProjectContact(projectId: string, input: ContactInput) {
  const now = new Date();

  return getDb().project.update({
    where: {
      id: projectId,
    },
    data: {
      currentStep: 'project_information',
      updatedAt: now,
      contact: {
        upsert: {
          create: {
            firstName: input.firstName,
            lastName: input.lastName,
            email: input.email,
            title: input.title,
            phoneNumber: input.phoneNumber,
            updatedAt: now,
          },
          update: {
            firstName: input.firstName,
            lastName: input.lastName,
            email: input.email,
            title: input.title,
            phoneNumber: input.phoneNumber,
            updatedAt: now,
          },
        },
      },
    },
    include: projectInclude,
  });
}

export function updateProjectInformation(
  projectId: string,
  input: ProjectInformationInput
) {
  const now = new Date();

  return getDb().project.update({
    where: {
      id: projectId,
    },
    data: {
      name: input.name,
      description: input.description,
      type: 'renewable_energy',
      infrastructureType: input.infrastructureType,
      projectStatus: input.projectStatus,
      targetInvestmentAmount: input.targetInvestmentAmount,
      targetInvestmentCurrency: 'GBP',
      raisedBefore: input.raisedBefore,
      websiteUrl: input.websiteUrl,
      socialUrl: input.socialUrl,
      currentStep: 'campaign_details',
      updatedAt: now,
      documents: input.proposalDocument
        ? {
            deleteMany: {
              kind: 'proposal',
            },
            create: {
              kind: 'proposal',
              fileName: input.proposalDocument.fileName,
              mimeType: input.proposalDocument.mimeType,
              sizeBytes: input.proposalDocument.sizeBytes,
              checksum: input.proposalDocument.checksum,
              storageUrl: input.proposalDocument.storageUrl,
              createdAt: now,
              updatedAt: now,
            },
          }
        : undefined,
    },
    include: projectInclude,
  });
}

export function upsertProjectCampaign(projectId: string, input: CampaignInput) {
  const now = new Date();

  return getDb().$transaction(async (tx) => {
    await tx.projectCreationMilestone.deleteMany({
      where: {
        projectId,
      },
    });

    await tx.project.update({
      where: {
        id: projectId,
      },
      data: {
        currentStep: 'review',
        updatedAt: now,
        campaign: {
          upsert: {
            create: {
              tokenName: input.tokenName,
              digitalAssetSupply: input.digitalAssetSupply,
              price: input.price,
              currency: input.currency,
              minRaise: input.minRaise,
              maxRaise: input.maxRaise,
              minContribution: input.minContribution,
              maxContribution: input.maxContribution,
              startDate: input.startDate,
              endDate: input.endDate,
              generalContractorWalletAddress:
                input.generalContractorWalletAddress,
              pledgeAddress: input.pledgeAddress,
              updatedAt: now,
            },
            update: {
              tokenName: input.tokenName,
              digitalAssetSupply: input.digitalAssetSupply,
              price: input.price,
              currency: input.currency,
              minRaise: input.minRaise,
              maxRaise: input.maxRaise,
              minContribution: input.minContribution,
              maxContribution: input.maxContribution,
              startDate: input.startDate,
              endDate: input.endDate,
              generalContractorWalletAddress:
                input.generalContractorWalletAddress,
              pledgeAddress: input.pledgeAddress,
              updatedAt: now,
            },
          },
        },
        milestones: {
          create: input.milestones.map((milestone, index) => ({
            name: milestone.name,
            cost: milestone.cost,
            endDate: milestone.endDate,
            sortOrder: index,
            createdAt: now,
            updatedAt: now,
          })),
        },
      },
    });

    return tx.project.findUniqueOrThrow({
      where: {
        id: projectId,
      },
      include: projectInclude,
    });
  });
}

export function submitProject(projectId: string) {
  const now = new Date();

  return getDb().project.update({
    where: {
      id: projectId,
    },
    data: {
      submissionStatus: 'submitted',
      currentStep: 'submitted',
      submittedAt: now,
      updatedAt: now,
    },
    include: projectInclude,
  });
}

import 'server-only';

import { ApiError } from '@/server/http';
import {
  createProjectDraft,
  findProjectForOwner,
  submitProject,
  updateProjectInformation,
  updateProjectSymbol,
  upsertProjectCampaign,
  upsertProjectContact,
  type ProjectWithDetails,
} from '@/server/repositories/projects';
import { authenticateAppRequest } from '@/server/services/auth';
import type {
  CampaignInput,
  ContactInput,
  ProjectInformationInput,
  ProjectSymbolInput,
} from '@/server/validation/projects';

async function getAuthenticatedProjectOwnerId(accessToken: string) {
  const { user } = await authenticateAppRequest(accessToken);

  if (user.role !== 'project_owner') {
    throw new ApiError('FORBIDDEN', 'Project owner account required.');
  }

  return user.id;
}

async function assertProjectOwner(projectId: string, accessToken: string) {
  const ownerUserId = await getAuthenticatedProjectOwnerId(accessToken);
  const project = await findProjectForOwner(projectId, ownerUserId);

  if (!project) {
    throw new ApiError('NOT_FOUND', 'Project not found.');
  }

  return project;
}

function serializeDecimal(
  value: { toString: () => string } | null | undefined
) {
  return value?.toString() ?? null;
}

function serializeDate(value: Date | null | undefined) {
  return value?.toISOString() ?? null;
}

function serializeProject(project: ProjectWithDetails) {
  return {
    id: project.id,
    owner_user_id: project.ownerUserId,
    name: project.name,
    description: project.description,
    type: project.type,
    infrastructure_type: project.infrastructureType,
    project_status: project.projectStatus,
    crowdfunding_model: project.crowdfundingModel,
    submission_status: project.submissionStatus,
    current_step: project.currentStep,
    digital_asset_symbol: project.digitalAssetSymbol,
    target_investment_amount: serializeDecimal(project.targetInvestmentAmount),
    target_investment_currency: project.targetInvestmentCurrency,
    raised_before: project.raisedBefore,
    website_url: project.websiteUrl,
    social_url: project.socialUrl,
    submitted_at: serializeDate(project.submittedAt),
    created_at: project.createdAt.toISOString(),
    updated_at: project.updatedAt.toISOString(),
    contact: project.contact
      ? {
          first_name: project.contact.firstName,
          last_name: project.contact.lastName,
          email: project.contact.email,
          title: project.contact.title,
          phone_number: project.contact.phoneNumber,
        }
      : null,
    campaign: project.campaign
      ? {
          token_name: project.campaign.tokenName,
          digital_asset_supply: serializeDecimal(
            project.campaign.digitalAssetSupply
          ),
          price: serializeDecimal(project.campaign.price),
          currency: project.campaign.currency,
          min_raise: serializeDecimal(project.campaign.minRaise),
          max_raise: serializeDecimal(project.campaign.maxRaise),
          min_contribution: serializeDecimal(project.campaign.minContribution),
          max_contribution: serializeDecimal(project.campaign.maxContribution),
          start_date: serializeDate(project.campaign.startDate),
          end_date: serializeDate(project.campaign.endDate),
          general_contractor_wallet_address:
            project.campaign.generalContractorWalletAddress,
          pledge_address: project.campaign.pledgeAddress,
        }
      : null,
    documents: project.documents.map((document) => ({
      id: document.id,
      kind: document.kind,
      file_name: document.fileName,
      mime_type: document.mimeType,
      size_bytes: document.sizeBytes,
      checksum: document.checksum,
      storage_url: document.storageUrl,
    })),
    milestones: project.milestones.map((milestone) => ({
      id: milestone.id,
      name: milestone.name,
      cost: serializeDecimal(milestone.cost),
      end_date: serializeDate(milestone.endDate),
      sort_order: milestone.sortOrder,
    })),
  };
}

